Console.Write("Entrez une quantité : ");
string? texte = Console.ReadLine();
if (!int.TryParse(texte, out int quantite) || quantite < 0) {
    Console.Error.WriteLine("Quantité invalide");
    return;
}
Console.WriteLine($"Double : {quantite * 2}");

